rules.replacement:
(_, value, unit) => {
        const units = { s: '秒', m: '分钟', h: '小时', d: '天', w: '周', mo: '个月', y: '年' };
        return `${value} ${units[unit]}前`;
    }

(_, duration) => {
        const units = { d: '天', h: '小时', m: '分钟', s: '秒' };
        const translated = duration.replace(/(\d+)([dhms])/g, (_, value, unit) => `${value} ${units[unit]}`);
        return `将在 ${translated.trim()} 后重置`;
    }
